const crypto = require('crypto');

const HMAC_SECRET   = $env['N8N_WEBHOOK_HMAC_SECRET'];
const MAX_SKEW_SECS = 300;

const item    = $input.first();
const headers = item.json.headers || {};

const sigHeader = headers['x-eduai-signature-256']   || '';
const tsHeader  = headers['x-eduai-timestamp']       || '';
const idempKey  = headers['x-eduai-idempotency-key'] || '';

const nowSecs = Math.floor(Date.now() / 1000);
const tsSecs  = parseInt(tsHeader, 10);
if (isNaN(tsSecs) || Math.abs(nowSecs - tsSecs) > MAX_SKEW_SECS) {
  throw new Error(`Timestamp rejected: skew=${nowSecs - tsSecs}s`);
}

const rawBody  = item.json.rawBody || JSON.stringify(item.json.body);
const expected = 'sha256=' + crypto.createHmac('sha256', HMAC_SECRET).update(rawBody, 'utf8').digest('hex');
const sigBuf = Buffer.from(sigHeader);
const expBuf = Buffer.from(expected);
if (sigBuf.length !== expBuf.length || !crypto.timingSafeEqual(sigBuf, expBuf)) {
  throw new Error('Signature verification failed');
}

const body = typeof rawBody === 'string' ? JSON.parse(rawBody) : rawBody;
return [{ json: { ...body, _idempotency_key: idempKey, _verified: true } }];

// ── Deliverable 2: Role Isolation ──────────────────────────────────────────
// The HITL workflow handles escalations for student and professor AI outputs.
// The SUBJECT (person whose report is under review) must be student/professor.
// This workflow is triggered internally by FastAPI, not by end-users directly.
const ALLOWED_ROLES = ['student', 'professor'];

const item = $input.first();
const role = (item.json.payload || {}).role || '';

if (!ALLOWED_ROLES.includes(role)) {
  console.error(JSON.stringify({
    level: 'error', message: 'hitl_role_rejected',
    role, allowed: ALLOWED_ROLES,
    event_id: item.json.event_id,
  }));
  throw new Error(`HITL: subject role '${role}' is not permitted. Allowed: ${ALLOWED_ROLES.join(', ')}`);
}

return [{ json: { ...item.json, _role_validated: true } }];

// Build the HITL notification payload.
// $execution.resumeUrl is the URL the admin must call to resume this execution.
// It is provided by n8n automatically for executions with Wait nodes.
const item    = $input.first();
const payload = item.json.payload || {};

const confidence = typeof payload.confidence_score === 'number' ? payload.confidence_score : null;
let severity = 'high';
if (confidence !== null) {
  severity = confidence < 0.25 ? 'critical' : confidence < 0.35 ? 'high' : 'moderate';
}

const escalationId = `esc-${item.json.event_id}`;

// $execution.resumeUrl is injected by n8n at execution start.
// The admin POSTs to this URL with { decision: 'approved'|'rejected', notes: '...' }
const resumeUrl = $execution.resumeUrl;

const notification = {
  escalation_id:   escalationId,
  resume_url:      resumeUrl,
  severity,
  confidence,
  file_id:         payload.file_id  || '',
  user_id:         payload.user_id  || '',
  role:            payload.role     || '',
  model_id:        payload.model_id || '',
  event_id:        item.json.event_id,
  correlation_id:  item.json.correlation_id,
  created_at:      new Date().toISOString(),
  message: `HITL review required: AI report confidence=${confidence} (${severity}) for ${payload.role} user ${payload.user_id}. Approve or reject at: ${resumeUrl}`,
};

console.log(JSON.stringify({
  level: 'info', message: 'hitl_notification_prepared',
  escalation_id:  escalationId,
  severity,
  resume_url:     resumeUrl ? resumeUrl.slice(0, 80) + '...' : 'n/a',
}));

return [{ json: { notification, escalation_id: escalationId, severity, event_id: item.json.event_id } }];

// Parse the admin's decision from the Wait node resume payload.
// The admin POST body should contain: { decision: 'approved'|'rejected', notes: '...' }
// $input.first() is what the admin POSTed to the resumeUrl.
const resumeData = $input.first().json;

const decision   = (resumeData.decision || '').toLowerCase().trim();
const notes      = resumeData.notes      || '';
const decidedBy  = resumeData.decided_by || resumeData.admin_id || 'unknown';
const resumedAt  = new Date().toISOString();

if (!['approved', 'rejected'].includes(decision)) {
  throw new Error(`Invalid decision '${decision}'. Must be 'approved' or 'rejected'.`);
}

const escalationId = $('Build HITL Notification').item.json.escalation_id;

console.log(JSON.stringify({
  level: 'info', message: 'hitl_decision_received',
  escalation_id: escalationId,
  decision,
  decided_by:    decidedBy,
  resumed_at:    resumedAt,
}));

return [{
  json: {
    escalation_id: escalationId,
    decision,
    notes,
    decided_by:  decidedBy,
    resumed_at:  resumedAt,
    event_id:    $('Verify HMAC Signature').item.json.event_id,
    correlation_id: $('Verify HMAC Signature').item.json.correlation_id,
  }
}];

const item = $input.first();
console.log(JSON.stringify({
  level: 'info', message: 'hitl_approved',
  escalation_id: item.json.escalation_id,
  decided_by:    item.json.decided_by,
  notes:         item.json.notes,
}));
// In production: mark the report as approved in Supabase,
// unblock the user notification pipeline, etc.
return [{ json: { ...item.json, outcome: 'approved', outcome_at: new Date().toISOString() } }];

const item = $input.first();
console.warn(JSON.stringify({
  level: 'warn', message: 'hitl_rejected',
  escalation_id: item.json.escalation_id,
  decided_by:    item.json.decided_by,
  notes:         item.json.notes,
}));
// In production: flag the report as needing reanalysis in Supabase,
// trigger a re-run of the LangGraph pipeline with stricter settings, etc.
return [{ json: { ...item.json, outcome: 'rejected', outcome_at: new Date().toISOString() } }];
